#!/usr/bin/env bash
# Strings, arrays, maps, classes, interfaces, closures, nullable values and `when`
# give the same results under `#` (the evaluator) as in the program's own code.
# tests/cases/lang-parity/*.ab are generated by tools/gen-lang-parity.py; each runs
# its cases both ways and exits 42 when every pair of results matches. A copy with
# one staged expression changed must fail (the harness can see a difference).
set -euo pipefail

compiler=${1:-build/ablac.bin}
project_root=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
output_directory="$project_root/build/lang-parity"
mkdir -p "$output_directory"

for source in "$project_root"/tests/cases/lang-parity/*.ab; do
    name=$(basename "$source" .ab)
    "$compiler" build "$source" -o "$output_directory/$name" --fast --no-cache
    set +e
    "$output_directory/$name"
    status=$?
    set -e
    [[ $status -eq 42 ]] || { echo "lang-parity: $name differs" >&2; exit 1; }
done

# Negative control: the staged copy of the first `size` case reports one more.
mutated="$output_directory/mutated.ab"
awk '/out.append\("size \$\{s.size\}/ { count++; if (count == 2) sub(/\$\{s.size\}/, "${s.size + 1}") } { print }' \
    "$project_root/tests/cases/lang-parity/strings.ab" > "$mutated"
cmp -s "$mutated" "$project_root/tests/cases/lang-parity/strings.ab" &&
    { echo "lang-parity: the negative control changed nothing" >&2; exit 1; }
"$compiler" build "$mutated" -o "$output_directory/mutated" --fast --no-cache
set +e
"$output_directory/mutated" > "$output_directory/mutated.log" 2>&1
status=$?
set -e
[[ $status -eq 1 ]] && grep -q 'staged:' "$output_directory/mutated.log" ||
    { echo "lang-parity: the negative control was not caught" >&2; exit 1; }
echo "lang parity: strings, collections, classes, closures, nullables and when match"
